SELECT c.city, DATE_TRUNC('MONTH', c.signup_date) AS signup_month, SUM(CASE WHEN we.event_type = 'add_to_cart' THEN we.duration_sec ELSE 0 END) AS add_to_cart_duration_sec, MIN(we.duration_sec) AS min_duration_sec FROM web_events we LEFT OUTER JOIN sessions s ON we.session_id = s.id LEFT OUTER JOIN customers c ON s.customer_id = c.id WHERE s.browser = 'Chrome' GROUP BY c.city, DATE_TRUNC('MONTH', c.signup_date) ORDER BY add_to_cart_duration_sec, min_duration_sec DESC
